import{_ as e,o as t,c as r,a2 as d}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Stamina y recuperación","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/stamina-and-reactive-combat.md","filePath":"es/guide/combat/stamina-and-reactive-combat.md"}'),n={name:"es/guide/combat/stamina-and-reactive-combat.md"};function i(s,a,o,c,l,p){return t(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="stamina-and-reactive-combat" tabindex="-1">Stamina y recuperación <a class="header-anchor" href="#stamina-and-reactive-combat" aria-label="Enlace permanente a &quot;Stamina y recuperación&quot;">​</a></h1><p><strong>Estado:</strong> Experimental para el perfil de recursos y tiempos · No implementado.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>La stamina hace competir el ataque, la defensa y la presión repetida.</li><li>La reserva Experimental es de 100; no fija la futura fórmula de Max Stamina.</li><li>Todas las fases de la acción deben terminar; jugar con prisas cuesta más y las entradas rechazadas no conceden un ataque.</li></ul><p>La stamina hace competir el ataque, la defensa y la presión repetida. Una DEX baja no debería convertir el juego básico en cámara lenta.</p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Regla de prueba</th><th>Valor / significado</th></tr></thead><tbody><tr><td>Reserva</td><td>100 de stamina</td></tr><tr><td>Recuperación de stamina</td><td>6/segundo tras 1000 ms sin una acción pagada; ninguna durante las fases de acción</td></tr><tr><td>Wind-up</td><td>Preparación antes del contacto</td></tr><tr><td>Ventana activa</td><td>Oportunidad de contacto, no golpes gratuitos repetidos</td></tr><tr><td>Recuperación</td><td>Debe terminar antes de la siguiente acción, incluida la defensa</td></tr><tr><td>Entrada rechazada</td><td>Sin ataque ni cargo de stamina</td></tr></tbody></table><h2 id="repeat-pressure" tabindex="-1">Presión repetida <a class="header-anchor" href="#repeat-pressure" aria-label="Enlace permanente a &quot;Presión repetida&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Banda</th><th>Multiplicador de coste</th><th>Multiplicador de recuperación</th><th>Precisión</th></tr></thead><tbody><tr><td>Normal</td><td>×1.00</td><td>×1.00</td><td>Sin penalización</td></tr><tr><td>Slightly rushed</td><td>×1.10</td><td>×1.05</td><td>−2 pp</td></tr><tr><td>Rushed</td><td>×1.25</td><td>×1.15</td><td>−5 pp</td></tr><tr><td>Spam</td><td>×1.50</td><td>×1.25</td><td>−10 pp</td></tr></tbody></table><p>Las bandas de Modern comparan los inicios aceptados con el ritmo de referencia; las entradas no disponibles no saltan las fases. Los factores de Flow y Familiarity también se aplican dentro de límites explícitos. Legacy comparte los costes base con una cadencia automática acotada.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Heavy Blow cuesta 28 antes de los modificadores. Fallar igualmente consume la acción y su recuperación; la presión sobre la stamina da al rival un motivo para provocarlo.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/es/guide/characters/stats.html">Stats</a> · <a href="/Syrolands-Public/es/game-design/combat/stamina-and-reactive-combat.html">Diseño completo de stamina</a> · <a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html">Cálculos exactos de prueba</a></p><p><span id="timing-without-broken-early-characters"></span><span id="manual-attacks-are-a-proposal"></span></p>',15)])])}const h=e(n,[["render",i]]);export{u as __pageData,h as default};
